using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public class StudioPreferenceLayoutValidation:EditorWindow {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static StudioControlsPreferences prefs;static StudioPreferenceLayoutValidation host;static int stage,checks;static string failure,beforeSettings,beforeHotkeys;static double next;static int errors;static bool captured;static string theme,settingsFile,hotkeysFile;
 static void Check(bool p,string m){if(!p)throw new Exception(m);checks++;}
 static void Page(int page)=>typeof(StudioControlsPreferences).GetField("page",F).SetValue(prefs,page);
 public static void Run(){EditorApplication.delayCall+=()=>{try{StudioControlsPreferences.Open();prefs=Resources.FindObjectsOfTypeAll<StudioControlsPreferences>().Single();Check(prefs.titleContent.text=="Modelling Studio Preferences","Wrong title");Check(prefs.minSize==new Vector2(780,560),"Wrong minimum size");prefs.Close();prefs=ScriptableObject.CreateInstance<StudioControlsPreferences>();prefs.position=new Rect(100,100,960,680);beforeSettings=JsonUtility.ToJson(StudioSettings.Current);theme=StudioSettings.Current.theme;StudioSettings.Current.theme="graphite";settingsFile=File.Exists(StudioPreferenceStore.SettingsPath)?File.ReadAllText(StudioPreferenceStore.SettingsPath):null;hotkeysFile=File.Exists(StudioPreferenceStore.HotkeysPath)?File.ReadAllText(StudioPreferenceStore.HotkeysPath):null;beforeHotkeys=Bindings();Application.logMessageReceived+=(s,t,k)=>{if(k==LogType.Error||k==LogType.Exception||k==LogType.Assert){errors++;failure=s+"\n"+t;}};host=CreateInstance<StudioPreferenceLayoutValidation>();host.position=new Rect(100,100,960,680);host.ShowUtility();next=EditorApplication.timeSinceStartup+.5;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}};}
 static string Bindings()=>string.Join("|",StudioShortcuts.Definitions.Select(d=>d.id+":"+string.Join(",",StudioShortcuts.Bindings(d.id).Select(b=>b.ToString()))));
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.2;try{if(failure!=null)throw new Exception(failure);host.SendEvent(new Event{type=EventType.Layout});host.SendEvent(new Event{type=EventType.Repaint});if(!captured)return;captured=false;if(stage==0){host.SendEvent(new Event{type=EventType.MouseDown,button=0,mousePosition=new Vector2(70,55)});host.SendEvent(new Event{type=EventType.MouseUp,button=0,mousePosition=new Vector2(70,55)});Check((int)typeof(StudioControlsPreferences).GetField("page",F).GetValue(prefs)==1,"Sidebar click did not change category");stage=1;return;}if(stage<5){Page(++stage);return;}if(stage==5){stage++;StudioSettings.Current.theme="porcelain";host.position=new Rect(100,100,780,560);prefs.position=host.position;Page(1);return;}StudioSettings.Current.theme=theme;Check(settingsFile==(File.Exists(StudioPreferenceStore.SettingsPath)?File.ReadAllText(StudioPreferenceStore.SettingsPath):null),"Browsing wrote settings file");Check(hotkeysFile==(File.Exists(StudioPreferenceStore.HotkeysPath)?File.ReadAllText(StudioPreferenceStore.HotkeysPath):null),"Browsing wrote hotkey file");Check(JsonUtility.ToJson(StudioSettings.Current)==beforeSettings,"Browsing rewrote settings");Check(Bindings()==beforeHotkeys,"Browsing rewrote hotkeys");Check(errors==0,"Native UI errors");Finish("PASS "+checks+" native layout, title, navigation and read-only browsing checks");}catch(Exception e){Finish(e.ToString());}}
 void OnGUI(){if(prefs==null)return;bool paint=Event.current.type==EventType.Repaint;RenderTexture rt=null;var old=RenderTexture.active;try{if(paint){rt=new RenderTexture(Mathf.RoundToInt(position.width),Mathf.RoundToInt(position.height),0);rt.Create();RenderTexture.active=rt;GL.PushMatrix();GL.Clear(true,true,Color.clear);GL.LoadPixelMatrix(0,rt.width,rt.height,0);}using(StudioTheme.Scope()){EditorGUI.DrawRect(new Rect(Vector2.zero,position.size),StudioTheme.Current.Panel);prefs.DrawControls();}if(paint&&!captured){
 var flags=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 var cache=typeof(GUILayoutUtility).GetProperty("current",flags)?.GetValue(null)??typeof(GUILayoutUtility).GetField("current",flags)?.GetValue(null);
 var top=cache.GetType().GetField("topLevel",flags).GetValue(cache);
 var dump=new System.Text.StringBuilder();
 void Walk(object item,int depth){var type=item.GetType();var rect=(Rect)type.GetField("rect",flags).GetValue(item);var style=(GUIStyle)type.GetField("style",flags)?.GetValue(item);if(style==null)style=(GUIStyle)type.GetProperty("style",flags)?.GetValue(item);dump.AppendLine(new string(' ',depth)+type.Name+" "+rect+" padding="+style?.padding+" overflow="+style?.overflow);var entries=type.GetField("entries",flags)?.GetValue(item) as System.Collections.IEnumerable;if(entries!=null)foreach(var child in entries)Walk(child,depth+1);}
 Walk(top,0);File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../preference-layout-rects-"+stage+".txt")),dump.ToString());
 var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();Check(t.GetPixels32().Select(c=>c.r).Distinct().Count()>20,"UI did not render");File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../modelling-preferences-"+stage+".png")),t.EncodeToPNG());Object.DestroyImmediate(t);captured=true;}}catch(Exception e){failure=e.ToString();}finally{if(paint){GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);}}}
 static void Finish(string r){EditorApplication.update-=Tick;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../modelling-preferences-result.txt")),r);EditorApplication.delayCall+=()=>{if(host)host.Close();if(prefs)Object.DestroyImmediate(prefs);EditorApplication.Exit(r.StartsWith("PASS")?0:1);};}
}



